final class Orthocal_Admin {
    static function boot($file) {
        add_action('admin_post_orthocal_cache',function(){
            if(!current_user_can('manage_options'))wp_die((esc_html(Orthocal_I18n::text('Insufficient permissions.')))); check_admin_referer('orthocal_cache');
            $action=sanitize_key($_POST['operation']??'');$message='';
            if($action==='data'){update_option('orthocal_cache_generation',wp_generate_uuid4(),false);$message=(Orthocal_I18n::text('Calendar data cache cleared.'));}
            elseif($action==='check'){Orthocal_Media_Cache::recheck();$message=(Orthocal_I18n::text('Local file checks have been queued.'));}
            elseif($action==='media'){$message=Orthocal_Media_Cache::clear()?(Orthocal_I18n::text('Local copies cleared.')):(Orthocal_I18n::text('Files are being updated. Please try again later.'));}
            set_transient('orthocal_admin_notice_'.get_current_user_id(),$message,60);
            wp_safe_redirect(admin_url('admin.php?page=orthocal&tab=connection'));exit;
        });
    }
